{
  "title": "The Mirror Breach",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver enters through a shattered window.",
      "visual_description": "A ruined ballroom with cracked mirrors and hanging chandeliers; the glass diver steps through a jagged window frame, helmet reflecting the broken city outside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a map of the cursed towers.",
      "visual_description": "Mara kneels on a dusty floor, spreading a parchment map marked with glowing ink; the tin fox stands at her shoulder, scanning the corridors.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a trap ahead.",
      "visual_description": "A dark hallway lined with old royal banners; the oracle lamp hovers, its flame eye flickering, casting long shadows of the banners.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scuttles past a patrol of armored figures.",
      "visual_description": "A narrow alley between collapsed walls; the tin fox presses against rubble, its blue eyes watching a patrol of armored figures march past.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara deciphers a magic door's riddle.",
      "visual_description": "A massive stone door carved with shifting runes; Mara traces the patterns with ink-stained fingers, while the glass diver waits nearby.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector snores on a pile of ledgers.",
      "visual_description": "A dusty office with a desk buried in stamped papers; the sleeping tax collector uses a thick ledger as a pillow, oblivious to the noise.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through a cursed mirror.",
      "visual_description": "A large, rippling mirror in a tower room; the glass diver's helmeted form passes through the liquid surface, coat trailing silver reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp illuminates a false corridor.",
      "visual_description": "A corridor that ends in a wall of thorns; the oracle lamp's glow reveals a hidden passage behind a rotten tapestry.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Mara marks a safe route past a crumbling tower.",
      "visual_description": "A leaning tower with loose stones and a broken spire; Mara draws a line on her map, the tin fox sniffing at the base.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector wakes briefly to stamp a form.",
      "visual_description": "A cluttered room with stacks of old ledgers; the sleeping tax collector opens one eye, mechanically stamps a paper, then falls back asleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver finds a key behind a moonlit window.",
      "visual_description": "A tall arched window with moonlight streaming through; the glass diver reaches through the glass, pulling out an iron key from a sill.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox triggers a pressure plate softly.",
      "visual_description": "A tiled floor with a faint pressure plate; the tin fox steps carefully, its key-wind tail ticking, avoiding a hidden dart mechanism.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara reads a cryptic note left by a previous traveler.",
      "visual_description": "A small alcove with a stone bench; Mara holds a torn note, ink faded, while the oracle lamp hovers to provide light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver peers into a cursed tower's heart.",
      "visual_description": "A circular room with a glowing orb at the center; the glass diver's helmet reflects the orb's light, revealing ghostly runes on the walls.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector is carried across a gap.",
      "visual_description": "A broken bridge span over a chasm; the tin fox and Mara carefully drag the sleeping tax collector on a makeshift sled.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp reveals the final exit route.",
      "visual_description": "A high balcony overlooking the ruined city; the oracle lamp points its flame toward a distant bridge, casting a long beam of light.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The group assembles at the bridge's entrance.",
      "visual_description": "A wide stone bridge with broken parapets; the glass diver, Mara, the tin fox, the oracle lamp, and the sleeping tax collector stand together, the city behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as the city collapses.",
      "visual_description": "The bridge shudders as towers fall in the distance; the group hurries across, the glass diver last, coat billowing, as the mirror city crumbles.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ],
  "title": "The Mirror Breach"
}

